static int write_file_exact(const char* path, const char* data)
{
	int fd = open(path, O_WRONLY);
	if (fd < 0) {
		perror(path);
		return -1;
	}
	size_t len = strlen(data);
	ssize_t ret = write(fd, data, len);
	if (ret != (ssize_t)len) {
		fprintf(stderr, "write %s failed ret=%zd errno=%d\n", path, ret, errno);
		close(fd);
		return -1;
	}
	close(fd);
	return 0;
}

static int write_userns_maps(pid_t pid, uid_t uid, gid_t gid)
{
	char path[128];
	char map[128];

	snprintf(path, sizeof(path), "/proc/%d/setgroups", pid);
	write_file_exact(path, "deny");

	snprintf(path, sizeof(path), "/proc/%d/uid_map", pid);
	snprintf(map, sizeof(map), "0 %d 1\n", uid);
	if (write_file_exact(path, map))
		return -1;

	snprintf(path, sizeof(path), "/proc/%d/gid_map", pid);
	snprintf(map, sizeof(map), "0 %d 1\n", gid);
	if (write_file_exact(path, map))
		return -1;

	return 0;
}

struct userns_child_args {
	int ready_fd;
};

__attribute__((aligned(64 << 10))) static char userns_stack[1 << 20];

static int userns_child(void* arg)
{
	struct userns_child_args* args = (struct userns_child_args*)arg;
	char token;

	if (read(args->ready_fd, &token, 1) != 1)
		return 1;
	close(args->ready_fd);

	if (setgid(0) || setuid(0)) {
		perror("setuid/setgid inside userns");
		return 1;
	}
	if (unshare(CLONE_NEWNS)) {
		perror("unshare(CLONE_NEWNS)");
		return 1;
	}
	mount(NULL, "/", NULL, MS_REC | MS_PRIVATE, NULL);
	chdir("/tmp");
	install_segv_handler();
	use_temporary_dir();
	execute_one();
	sleep(1);
	return 0;
}

int main(void)
{
		syscall(__NR_mmap, /*addr=*/0x1ffffffff000ul, /*len=*/0x1000ul, /*prot=*/0ul, /*flags=MAP_FIXED|MAP_ANONYMOUS|MAP_PRIVATE*/0x32ul, /*fd=*/(intptr_t)-1, /*offset=*/0ul);
	syscall(__NR_mmap, /*addr=*/0x200000000000ul, /*len=*/0x1000000ul, /*prot=PROT_WRITE|PROT_READ|PROT_EXEC*/7ul, /*flags=MAP_FIXED|MAP_ANONYMOUS|MAP_PRIVATE*/0x32ul, /*fd=*/(intptr_t)-1, /*offset=*/0ul);
	syscall(__NR_mmap, /*addr=*/0x200001000000ul, /*len=*/0x1000ul, /*prot=*/0ul, /*flags=MAP_FIXED|MAP_ANONYMOUS|MAP_PRIVATE*/0x32ul, /*fd=*/(intptr_t)-1, /*offset=*/0ul);
	int ready[2];
	if (pipe(ready)) {
		perror("pipe");
		return 1;
	}

	struct userns_child_args args = {.ready_fd = ready[0]};
	pid_t pid = clone(userns_child, &userns_stack[sizeof(userns_stack) - 64],
			  CLONE_NEWUSER | SIGCHLD, &args);
	if (pid < 0) {
		perror("clone(CLONE_NEWUSER)");
		return 1;
	}
	close(ready[0]);

	if (write_userns_maps(pid, getuid(), getgid())) {
		kill(pid, SIGKILL);
		close(ready[1]);
		return 1;
	}
	if (write(ready[1], "x", 1) != 1) {
		perror("signal child");
		kill(pid, SIGKILL);
		close(ready[1]);
		return 1;
	}
	close(ready[1]);

	int status = 0;
	waitpid(pid, &status, 0);
	if (WIFEXITED(status))
		return WEXITSTATUS(status);
	return 1;
}
